//! The Film Set Objects pack, as the pack drew it. Written by
//! `tools/fso_import.py` — edit that, not this.
//!
//! A picture faces whichever way the pack drew it; `turn` sets it east.
//! `w`/`h` are its size in metres as the image lies, before any turn.

pub struct Art {
    pub id: &'static str,
    pub name: &'static str,
    pub group: &'static str,
    /// `camera`, `light`, `fixture` (a light giving none), `grip`, `set`, `person`.
    pub role: &'static str,
    /// For a person: the pose it shows.
    pub pose: &'static str,
    /// Degrees the picture is turned to face east, the way the plan faces things.
    pub turn: f64,
    pub px_w: u32,
    pub px_h: u32,
    pub w: f64,
    pub h: f64,
    pub beam: f64,
    pub reach: f64,
    pub kelvin: f64,
    /// The PNG, or empty where the build leaves the pack out.
    pub png: &'static [u8],
}

/// The picture itself, where the build carries the pack (the Mac and
/// iPhone); empty in the portal's builds, which fetch the file.
#[cfg(feature = "fso-art")]
macro_rules! png {
    ($p:literal) => {
        include_bytes!($p)
    };
}
#[cfg(not(feature = "fso-art"))]
macro_rules! png {
    ($p:literal) => {
        &[]
    };
}

